mapper.select:
SELECT dr.id, dr.resource_name, dr.resource_url, dr.resource_size, dr.resource_type, dr.resource_format, dr.resource_description, dr.resource_tags, dr.resource_status, dr.resource_creator, ui.user_name as resource_creator_name, ui.image as resource_creator_avatar, dr.resource_update_time, dr.resource_create_time, dr.resource_is_public, dr.resource_bind_content_id, dr.resource_bind_content_type, dr.vip_resource, dr.download_count, COALESCE(match_score.interest_score, 0) AS interest_score FROM download_resource dr LEFT JOIN ( SELECT dr_inner.id AS resource_id, SUM(ui.weight) AS interest_score FROM download_resource dr_inner INNER JOIN user_interest ui ON FIND_IN_SET(CAST(ui.tag_id AS CHAR) COLLATE utf8mb4_unicode_ci, dr_inner.resource_tags) > 0 WHERE ui.user_id = #{userId} AND dr_inner.resource_status = 1 GROUP BY dr_inner.id ) match_score ON dr.id = match_score.resource_id INNER JOIN user_info ui ON dr.resource_creator = ui.user_id WHERE dr.resource_status = 1 AND dr.resource_is_public = 1
AND dr.resource_type IN
#{categoryName}
AND dr.vip_resource = 1
AND ( dr.resource_create_time < #{lastCreateTime} OR ( dr.resource_create_time = #{lastCreateTime} AND dr.id < #{lastId} ) )
ORDER BY interest_score DESC, dr.resource_create_time DESC, dr.id DESC LIMIT #{size}
